import { mkdir, readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const SCRIPT_DIR = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(SCRIPT_DIR, "..");
const OUTPUT_DIR = path.join(REPO_ROOT, "data");
const INPUT_JSON = path.join(OUTPUT_DIR, "anilist-anime-candidates.json");
const OUTPUT_TS = path.join(OUTPUT_DIR, "anilist-anime-candidates.catalog.ts");

const toTsCatalog = (items) => `// Generated by scripts/generate-anilist-catalog.mjs.
// Do not edit directly. Edit data/anilist-anime-candidates.json instead.

export const anilistAnimeCandidates = ${JSON.stringify(items, null, 2)} as const;
`;

const main = async () => {
  const payload = JSON.parse(await readFile(INPUT_JSON, "utf8"));
  const candidates = payload.candidates ?? [];

  await mkdir(OUTPUT_DIR, { recursive: true });
  await writeFile(OUTPUT_TS, toTsCatalog(candidates));

  console.log(`Generated ${OUTPUT_TS} from ${INPUT_JSON}.`);
};

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
